:root {
  color-scheme: light dark;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
}

body {
  margin: 0;
  background: canvas;
  color: canvastext;
}

#app {
  max-width: 42rem;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

form#note-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1rem;
  border: 1px solid color-mix(in srgb, canvastext 20%, transparent);
  border-radius: 0.5rem;
  margin-bottom: 1.5rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

input,
textarea {
  font: inherit;
  padding: 0.5rem;
  border: 1px solid color-mix(in srgb, canvastext 30%, transparent);
  border-radius: 0.375rem;
  background: canvas;
  color: canvastext;
}

.hint {
  margin: 0;
  font-size: 0.8rem;
  opacity: 0.75;
}

button[type="submit"] {
  align-self: flex-start;
  font: inherit;
  padding: 0.5rem 1.25rem;
  border: none;
  border-radius: 0.375rem;
  background: #0f766e;
  color: white;
  cursor: pointer;
}

button[type="submit"]:hover {
  background: #0b5c56;
}

.search-bar {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin-bottom: 1.5rem;
}

#results-line {
  margin: 0;
  font-size: 0.85rem;
  opacity: 0.8;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.note {
  padding: 1rem;
  border: 1px solid color-mix(in srgb, canvastext 20%, transparent);
  border-radius: 0.5rem;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.25rem 0.75rem;
}

.note[aria-current="true"] {
  border-color: #0f766e;
  box-shadow: 0 0 0 2px color-mix(in srgb, #0f766e 40%, transparent);
}

.note-avatar {
  grid-row: span 2;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  object-fit: cover;
}

.note-title {
  grid-column: 2;
  font: inherit;
  font-weight: 700;
