import { chromium } from '@playwright/test';
const browser = await chromium.launch();
const page = await browser.newPage();
const errors = [];
page.on('pageerror', e => errors.push(String(e)));
page.on('console', m => m.type() === 'error' && errors.push(m.text()));

await page.goto('http://127.0.0.1:4555/');
await page.waitForTimeout(300);

// Check rich text rendering of fixture note 1 (bold)
const boldExists = await page.$eval('article[data-note-id="1"] .note-body b', el => el.textContent);
console.log('bold text:', boldExists);

// Check link rendering fixture 4
const link = await page.$eval('article[data-note-id="4"] .note-body a', el => ({ href: el.getAttribute('href'), text: el.textContent }));
console.log('link:', JSON.stringify(link));

// Search
await page.fill('#search', 'port');
await page.waitForTimeout(200);
const resultsLine = await page.$eval('#results-line', el => el.textContent);
console.log('results line:', resultsLine);
const hash1 = await page.evaluate(() => location.hash);
console.log('hash after search:', hash1);

// Click a note title that matches "port" search, e.g. note 1 "Welcome to Porto Notes"
const titleBtns = await page.$$('.note-title');
console.log('visible note count after search:', titleBtns.length);
await titleBtns[0].click();
await page.waitForTimeout(200);
const hash2 = await page.evaluate(() => location.hash);
console.log('hash after selecting note:', hash2);
const ariaCurrent = await page.$eval('article[aria-current="true"]', el => el.dataset.noteId);
console.log('aria-current note id:', ariaCurrent);

// Reload and confirm restoration
await page.reload();
await page.waitForTimeout(300);
const searchVal = await page.$eval('#search', el => el.value);
console.log('search value after reload:', searchVal);
const ariaCurrent2 = await page.$eval('article[aria-current="true"]', el => el.dataset.noteId);
console.log('aria-current after reload:', ariaCurrent2);

// Submit a new note with rich text + XSS attempt
await page.fill('#title', 'Test <img src=x onerror=alert(1)>');
await page.fill('#body', 'Hello <b>world</b> and <script>alert(2)</script> visit <a href="javascript:alert(3)">bad</a> and <a href="https://example.com">good</a>\nnew line');
await page.fill('#avatar', 'javascript:alert(4)');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(300);
const newNote = await page.$('article[data-note-id="7"]');
console.log('new note exists:', !!newNote);
if (newNote) {
  const html = await newNote.evaluate(el => el.querySelector('.note-body').innerHTML);
  console.log('new note body innerHTML:', html);
  const titleText = await newNote.evaluate(el => el.querySelector('.note-title').textContent);
  console.log('new note title text:', titleText);
  const hasAvatarImg = await newNote.evaluate(el => !!el.querySelector('.note-avatar'));
  console.log('new note has avatar img (should be false, unsafe url):', hasAvatarImg);
}
console.log('page errors:', errors);
await browser.close();
process.exit(0);
